'use strict';
const R=Research,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=1)=>n==null||!Number.isFinite(n)?'—':n.toLocaleString('en-GB',{minimumFractionDigits:d,maximumFractionDigits:d});
const clone=x=>JSON.parse(JSON.stringify(x));
const sample={name:'Aurora Technology',ticker:'AURA',currency:'USD',sample:true,source:'Illustrative financial statements · fictional company',provenance:{},history:[
{year:2022,revenue:960,cogs:374,grossProfit:586,opex:436,ebit:150,da:43,capex:75,nwc:6,cfo:170,netIncome:104,cash:195,debt:410,equity:620,assets:1400,liabilities:780,shares:125,price:17.5},
{year:2023,revenue:1080,cogs:400,grossProfit:680,opex:497,ebit:183,da:48,capex:82,nwc:8,cfo:196,netIncome:129,cash:215,debt:395,equity:700,assets:1500,liabilities:800,shares:125,price:19},
{year:2024,revenue:1240,cogs:434,grossProfit:806,opex:570,ebit:236,da:54,capex:93,nwc:11,cfo:237,netIncome:168,cash:238,debt:376,equity:810,assets:1630,liabilities:820,shares:123,price:23.5},
{year:2025,revenue:1435,cogs:488,grossProfit:947,opex:649,ebit:298,da:62,capex:112,nwc:14,cfo:288,netIncome:213,cash:265,debt:348,equity:952,assets:1790,liabilities:838,shares:120,price:26.8}]};
let company=clone(sample),a=R.defaults(company),cases=[],page='analysis',metric='revenue',pending=null,lastChange=null;
let wc={rf:4,beta:1.1,erp:5,kd:5.5,tax:25,equity:80,debt:20};
const symbols={USD:'$',GBP:'£',EUR:'€'},money=n=>(n<0?'-':'')+symbols[company.currency]+fmt(n==null?null:Math.abs(n),2);
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000);}
function download(name,body,type='application/json'){const url=URL.createObjectURL(new Blob([body],{type})),el=document.createElement('a');el.href=url;el.download=name;el.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function go(p){page=p;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));$('#page-label').textContent=({analysis:'Financial analysis',sources:'Data & verification',valuation:'Valuation workbench',scenarios:'Scenario comparison'})[p];render();}
function heading(kicker,title,sub,extra=''){return `<div class="heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="subtext">${sub}</p></div>${extra}</div>`;}
function strip(){const h=company.history;return `<div class="company-strip"><div class="company-logo">${esc(company.ticker.slice(0,1))}</div><div><strong>${esc(company.name)}</strong><small>${esc(company.ticker)} · ${company.sample?'Illustrative technology business':'User-provided company financials'}</small></div><div class="right"><span>${h[0].year}–${h.at(-1).year} historical</span><span>${esc(company.currency)} millions</span><span class="tag ${company.sample?'sample':''}">${company.sample?'FICTIONAL SAMPLE':'IMPORTED DATA'}</span></div></div>`;}
function kpi(label,value,foot,inspect=''){return `<div class="kpi"><div class="kpi-label">${label}${inspect?`<button class="formula-btn" data-inspect="${inspect}" aria-label="Inspect ${label}">↗</button>`:''}</div><div class="kpi-value">${value}</div><div class="kpi-foot">${foot}</div></div>`;}
function table(headers,rows,cls=''){return `<div class="table-wrap"><table class="${cls}"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function chart(){const hs=company.history,vals=hs.map((h,i)=>R.metrics(h,hs[i-1])[metric]);const valid=vals.filter(v=>v!=null);if(!valid.length)return '<div class="empty">Map the required source figures to display this metric.</div>';let max=Math.max(...valid,0)*1.2||1,min=Math.min(...valid,0)*1.2;const W=650,H=237,left=54,right=22,top=20,bottom=38,ph=H-top-bottom,pw=W-left-right,yp=v=>top+(max-v)/(max-min)*ph,step=pw/hs.length,bw=Math.min(65,step*.48);let svg='';for(let i=0;i<5;i++){const v=min+(max-min)*i/4,y=yp(v);svg+=`<line x1="${left}" x2="${W-right}" y1="${y}" y2="${y}" stroke="#263346" stroke-dasharray="3 4"/><text x="${left-10}" y="${y+4}" text-anchor="end" fill="#7e91ac" font-size="10">${fmt(v,0)}</text>`;}
 vals.forEach((v,i)=>{const x=left+step*(i+.5);if(v!=null)svg+=`<rect x="${x-bw/2}" y="${Math.min(yp(v),yp(0))}" width="${bw}" height="${Math.max(1,Math.abs(yp(v)-yp(0)))}" rx="3" fill="${i===vals.length-1?'#84aefa':'#3c5d8e'}"><title>${hs[i].year}: ${fmt(v)} ${company.currency}m</title></rect><text x="${x}" y="${yp(v)+(v>=0?-9:17)}" text-anchor="middle" fill="#bacce5" font-size="11">${fmt(v,0)}</text>`;svg+=`<text x="${x}" y="${H-12}" text-anchor="middle" fill="#8397b1" font-size="10">${hs[i].year}</text>`;});return `<div class="chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Historical ${metric} chart. Exact values are in the financial table below.">${svg}</svg></div><div class="chart-foot"><i></i> ${esc(({revenue:'Revenue',ebitda:'EBITDA',fcf:'Cash flow after CapEx'})[metric])} · ${company.currency} millions · ${company.sample?'Illustrative data':'Confirmed source mappings'}</div>`;}
function analysis(){const hs=company.history,h=hs.at(-1),p=hs.at(-2),m=R.metrics(h,p),cagr=100*((h.revenue/hs[0].revenue)**(1/(h.year-hs[0].year))-1),checks=R.checks(company),review=checks.filter(x=>x.status==='review').length,pass=checks.filter(x=>x.status==='pass').length;
 return heading('COMPANY RESEARCH / HISTORICAL PERFORMANCE','Understand the business.','Explore the financial story before building your valuation.',`<button class="stage-link" data-page="valuation">Continue to valuation →</button>`)+strip()+`<div class="kpis">${kpi('Revenue',symbols[company.currency]+fmt(h.revenue,0)+'m',`${m.growth==null?'YoY unavailable':`<span class="positive">${fmt(m.growth*100)}% YoY</span>`} · FY${h.year}`,'revenue')}${kpi('EBITDA',m.ebitda==null?'—':symbols[company.currency]+fmt(m.ebitda,0)+'m',m.ebitda==null?'D&A and EBIT required':fmt(m.ebitda/h.revenue*100)+'% EBITDA margin','ebitda')}${kpi('Operating margin',fmt(m.operatingMargin==null?null:m.operatingMargin*100)+'%', 'EBIT / revenue · latest financial year','operatingMargin')}${kpi('Cash flow after CapEx',m.fcf==null?'—':symbols[company.currency]+fmt(m.fcf,0)+'m','Operating cash flow less capital expenditure','fcf')}</div>
 <div class="grid"><section class="panel"><div class="panel-head"><div><h2>Financial performance</h2><p>A view across the operating history</p></div><div class="segment">${['revenue','ebitda','fcf'].map(k=>`<button data-metric="${k}" class="${metric===k?'selected':''}">${{revenue:'Revenue',ebitda:'EBITDA',fcf:'Cash flow'}[k]}</button>`).join('')}</div></div>${chart()}</section><section class="panel"><div class="panel-head"><div><h2>Research observations</h2><p>Calculated from the available statements</p></div><span class="tag">${h.year}</span></div><div class="panel-body"><div class="insight"><h3><span class="num">01</span> ${fmt(cagr)}% historical revenue CAGR</h3><p>Annualised across ${h.year-hs[0].year} years. A reference for your forecast, not a growth prediction.</p></div><div class="insight"><h3><span class="num">02</span> ${m.leverage==null?'Leverage needs more data':fmt(m.leverage,2)+'× net debt / EBITDA'}</h3><p>${m.leverage==null?'Map cash, interest-bearing debt, EBIT and D&A.':'Uses the latest reported balance sheet and full-year EBITDA.'}</p></div><div class="insight"><h3><span class="num">03</span> ${review?review+' reconciliation flags':pass+' accounting checks passed'}</h3><p>${review?'Review the differences before relying on these financials.':'Checks cover only mapped figures. Missing checks remain explicitly unavailable.'} <button class="stage-link" data-page="sources">Review →</button></p></div></div></section></div>
 <section class="panel"><div class="panel-head"><div><h2>Historical financials & ratios</h2><p>Click a metric to inspect its definition and source inputs.</p></div><span class="tag">${company.currency}m, except ratios</span></div>${table(['Metric',...hs.map(h=>'FY'+h.year)], [['revenue','Revenue',0],['ebitda','EBITDA',0],['ebit','Operating profit / EBIT',0],['grossMargin','Gross margin',1],['operatingMargin','Operating margin',1],['fcf','Cash flow after CapEx',0],['fcfConversion','Cash flow / net income',1],['roic','ROIC · assumed 25% tax',1],['leverage','Net debt / EBITDA',2]].map(([key,label,type])=>[`<button class="formula-btn" data-inspect="${key}">${label}</button>`,...hs.map((h,i)=>{const v=R.metrics(h,hs[i-1])[key];return v==null?'—':fmt(v*(type===1?100:1),type===2?2:1)+(type===1?'%':type===2?'×':'');})]))}<div class="chart-foot">— = unavailable or not meaningful. ROIC uses average (debt + equity − cash); financial institutions require a different framework.</div></section>`;
}
function rawPreview(){const ys=[...new Set(pending.info.candidates.flatMap(c=>Object.keys(c.values)))].sort();return `<details class="raw-preview"><summary>Inspect source figures (${pending.info.candidates.length} rows)</summary>${table(['Worksheet / row','Source label',...ys],pending.info.candidates.map(c=>[esc(c.sheet)+' · '+c.row,esc(c.label),...ys.map(y=>esc(c.values[y]??'—'))]))}</details>`;}
function daReviewPanel(){
 const candidates=pending.info.daSuggestions||[];
 const selected=pending.info.candidates.find(c=>c.id===pending.mapping.da);
 const years=Object.keys(pending.info.candidates.find(c=>c.id===pending.mapping.revenue)?.values||{}).sort();
 const o=pending.daOverride;
 return `<div class="panel-body da-review"><h2>D&A interpretation</h2><p class="subtext">${selected&&!R.daReview(selected.label)?'A D&A row is selected. Review its definition and units before importing.':candidates.length?'Potential D&A-related lines found. Review the accounting definition before using them.':'No confirmed D&A row selected. You can leave this field unavailable or enter verified figures from the notes.'}</p>
 ${candidates.map(c=>`<div class="hint amber"><strong>${esc(c.label)}</strong><br>${esc(c.sheet)} · row ${c.row} · ${Object.entries(c.values).map(([y,v])=>`${y}: ${esc(v??'—')}`).join(' / ')} (original source units)<br>${esc(c.reason)}</div>`).join('')}
 <label><input type="checkbox" id="da-override-enabled" ${o.enabled?'checked':''}> Enter verified D&A from supporting notes</label>
 ${o.enabled?`<div class="hint">Enter annual depreciation plus amortisation in <strong>${esc(pending.currency)} millions</strong>. These figures replace the D&A row mapping only. Exclude other adjustments and avoid double-counting. Blank years remain unavailable.</div><div class="form-grid">${years.map(y=>`<label>FY${y} D&A, millions<input data-da-year="${y}" type="number" min="0" step="any" value="${esc(o.values[y]??'')}"></label>`).join('')}</div><label class="da-source">Source reference and calculation<input id="da-source-note" maxlength="1000" placeholder="e.g. Annual report note, page, depreciation + amortisation" value="${esc(o.sourceNote)}"></label><label><input id="da-verified" type="checkbox" ${o.confirmed?'checked':''}> I verified that these annual D&A figures exclude other adjustments.</label>`:'<p class="subtext">If D&A remains unavailable, historical EBITDA and net debt / EBITDA remain unavailable too. Forecast D&A remains an explicit analyst assumption.</p>'}</div>`;
}
function sources(){let html=heading('DATA WORKFLOW / IMPORT → VERIFY','Evidence before assumptions.','Map financial statements across worksheets, confirm the interpretation, then analyse.');if(!pending){html+=`<section class="panel"><div class="panel-body"><div class="upload" id="drop"><div class="upload-icon">↥</div><h2>Bring your company financials</h2><p>Drop a CSV or Excel workbook here. Income statement, balance sheet and cash flow tabs can be mapped together.</p><button class="primary" id="choose-file">Choose .csv or .xlsx</button> <button id="sample-import">Use sample statements</button><p>Up to 8 MB · Annual columns · Processed locally · No PDF extraction</p></div><div class="hint">Use line items in rows and years in columns. Headers such as 2024 or FY2024 are supported. Exact terminology matches are suggested automatically. D&A-related lines with uncertain definitions are flagged for review. <a href="samples/aurora-financials.csv" download>Download a sample CSV</a>.</div></div></section>`;}else{html+=`<section class="panel"><div class="panel-head"><div><h2>Review source mapping</h2><p>${esc(pending.source)} · ${pending.info.candidates.length} candidate rows across worksheets</p></div><button id="cancel-import">Cancel</button></div><div class="panel-body"><div class="form-grid"><label>Company name<input id="company-name" value="${esc(pending.name)}" maxlength="90"></label><label>Ticker / identifier<input id="company-ticker" value="${esc(pending.ticker)}" maxlength="12"></label><label>Reporting currency<select id="currency">${['USD','GBP','EUR'].map(c=>`<option ${pending.currency===c?'selected':''}>${c}</option>`).join('')}</select></label></div>${pending.info.warnings.map(w=>`<div class="hint amber">${esc(w)}</div>`).join('')}<div class="hint">Confirm units for each row. Shares can use different units from financial amounts. CapEx, D&A and costs use positive magnitudes; ΔNWC is positive for a cash investment. “Reverse sign” is an explicit conversion. Currency selection does not convert currencies.</div></div>${rawPreview()}${daReviewPanel()}${table(['Financial field','Worksheet / source row','Source units','Reverse sign'],R.fields.map(([key,label])=>{const opts=pending.info.candidates.map(c=>`<option value="${esc(c.id)}" ${pending.mapping[key]===c.id?'selected':''}>${esc(c.sheet+' · '+c.label+' [row '+c.row+']'+(key==='da'&&R.daReview(c.label)?' — REVIEW REQUIRED':''))}</option>`).join('');return [label+(key==='da'&&pending.daOverride.enabled?'<span class="source">Verified figures below replace this mapping.</span>':''),`<select data-map="${key}" aria-label="Map ${label}"><option value="">Not available</option>${opts}</select>`,`<select data-unit="${key}" aria-label="Units for ${label}" ${key==='price'?'disabled':''}>${[[1,'Units'],[1000,'Thousands'],[1e6,'Millions']].map(([v,t])=>`<option value="${v}" ${+(pending.units[key]??(key==='price'?1:1e6))===v?'selected':''}>${t}</option>`).join('')}</select>`,`<input type="checkbox" data-sign="${key}" aria-label="Reverse sign for ${label}" ${pending.reverse[key]?'checked':''}>`];}))}<div class="panel-body"><label><input type="checkbox" id="confirm-mapping" ${pending.confirm?'checked':''}> I reviewed the annual periods, units, definitions and selected mappings.</label><div id="import-error"></div><div class="actions"><button class="primary" id="apply-import">Confirm & analyse financials →</button><span class="subtext">Revenue for at least two years is required. Other fields may remain missing.</span></div></div></section>`;}
 const checks=R.checks(company);html+=strip()+`<section class="panel"><div class="panel-head"><div><h2>Statement reconciliation</h2><p>Rounding tolerance: greater of 0.01m or 0.5% of the compared balances.</p></div><span class="tag">${company.sample?'SAMPLE':'CURRENT DATA'}</span></div><div class="panel-body"><div class="checks-summary">${['pass','review','unavailable'].map(s=>`<span class="pill ${s}">${checks.filter(x=>x.status===s).length} ${s==='pass'?'passed':s}</span>`).join('')}</div><p class="subtext">Operating expense definitions vary. A discrepancy is a review flag, not proof of an accounting error.</p></div>${table(['Year','Accounting identity','Result','Detail'],checks.map(c=>[c.year,c.name,`<span class="pill ${c.status}">${c.status}</span>`,esc(c.detail)]))}</section><section class="panel"><div class="panel-head"><div><h2>Source register</h2><p>Confirmed mappings and transformations, retained in your downloadable project.</p></div></div>${company.sample?'<div class="panel-body subtext">All sample figures are fictional, including the added balance-sheet and cash-flow statements.</div>':table(['Field','Source','Units','Sign'],Object.entries(company.provenance).map(([k,v])=>[esc(R.fields.find(f=>f[0]===k)?.[1]||k),esc(v.sheet+' · '+(v.method==='analyst-verified'?v.sourceNote:'row '+v.row+' · '+v.label)),fmt(v.unit,0),v.sign===-1?'Reversed':'Original']))}</section>`;return html;}
function forecastInputs(){return table(['Forecast assumption',...a.years.map((_,i)=>company.history.at(-1).year+i+1+'E')],[['growth','Revenue growth, %'],['margin','EBIT margin, %'],['da','D&A / revenue, %'],['capex','CapEx / revenue, %'],['nwc','ΔNWC / change in revenue, %']].map(([k,label])=>[label,...a.years.map((y,i)=>`<input aria-label="${label} year ${i+1}" type="number" step="0.1" data-year="${i}" data-assumption="${k}" value="${Number.isFinite(y[k])?Number(y[k].toFixed(3)):''}">`)]));}
function input(k,label){return `<label>${label}<input type="number" step="any" data-global="${k}" value="${a[k]??''}"></label>`;}
function valuation(){let r,error;try{r=R.dcf(company,a);}catch(e){error=e.message;}const h=company.history.at(-1);return heading('VALUATION / FIVE-YEAR DCF','Make every assumption visible.','Build an explicit forecast, inspect the cash flows, and understand what drives value.')+strip()+`<div class="hint">Blue inputs are analyst assumptions. Forecast starting ratios use history where available; otherwise EBIT margin 20%, D&A 4% and CapEx 6% are assumptions. ΔNWC defaults to 10% of the change in revenue, tax to 25%, WACC to 9%, and terminal growth to 2.5%. Missing cash and debt remain blank. Supply diluted shares and confirm all equity-bridge inputs, including zero balances and any material adjustments. Reference share price is optional and is used only for upside comparison.</div>${error?`<div class="error">${esc(error)}</div>`:''}${r?`<div class="kpis">${kpi('DCF value / share',money(r.price),'Model-implied value · not a recommendation','dcf')}${kpi('Versus reference price',r.upside==null?'Unavailable':fmt(r.upside)+'%',a.marketPrice==null?'Add an optional reference price to calculate upside':money(a.marketPrice)+' user-supplied reference price')}${kpi('Enterprise value',symbols[company.currency]+fmt(r.ev,0)+'m','PV of cash flows + PV of terminal value','ev')}${kpi('Terminal value weight',fmt(r.terminalWeight)+'%','Share of enterprise value from terminal period','terminal')}</div>`:''}${lastChange?`<div class="hint">Last change: ${esc(lastChange.label)}. Model value moved from ${money(lastChange.before)} to ${money(lastChange.after)} (${money(lastChange.after-lastChange.before)} per share), holding other inputs fixed.</div>`:''}
 <section class="panel"><div class="panel-head"><div><h2>Operating assumptions</h2><p>Edit each forecast year independently. Inputs are percentages.</p></div><button id="reset-assumptions">Reset assumptions</button></div>${forecastInputs()}</section><div class="grid"><section class="panel"><div class="panel-head"><div><h2>Discount rate & equity bridge</h2><p>Amounts in ${company.currency}m; share count in millions.</p></div></div><div class="panel-body"><div class="form-grid">${input('wacc','WACC, %')}${input('terminalGrowth','Terminal growth, %')}${input('tax','Cash tax, %')}${input('cash','Cash & equivalents')}${input('debt','Interest-bearing debt')}${input('shares','Diluted shares')}${input('minority','Non-controlling interests')}${input('preferred','Preferred capital')}${input('other','Other non-operating assets')}${input('marketPrice','Reference share price (optional)')}</div><div class="hint ${R.bridgeConfirmed(a)?'':'amber'}">${R.bridgeConfirmed(a)?'Equity-bridge inputs confirmed.':'Valuation incomplete: review cash, debt, non-controlling interests, preferred capital, other non-operating assets and diluted shares. Zero means confirmed none, not missing. Include material lease, pension or other claims in the appropriate balance; avoid double-counting.'}</div><label><input type="checkbox" id="confirm-bridge" ${R.bridgeConfirmed(a)?'checked':''}> I reviewed these equity-bridge inputs, including zero balances and material adjustments.</label></div></section><section class="panel"><div class="panel-head"><div><h2>WACC builder</h2><p>CAPM + after-tax cost of debt</p></div><span class="tag">ASSUMPTIONS</span></div><div class="panel-body"><div class="form-grid">${[['rf','Risk-free rate, %'],['beta','Levered beta'],['erp','Equity risk premium, %'],['kd','Pre-tax debt cost, %'],['tax','Tax rate, %'],['equity','Market equity weight'],['debt','Market debt weight']].map(([k,l])=>`<label>${l}<input type="number" step="any" data-wacc="${k}" value="${wc[k]}"></label>`).join('')}</div><div id="wacc-result" class="hint">${waccText()}</div><button id="apply-wacc">Apply to DCF</button></div></section></div>${r?`<section class="panel"><div class="panel-head"><div><h2>Forecast cash-flow schedule</h2><p>End-of-year discounting · no tax benefit assumed on operating losses</p></div><button id="export-csv">↓ Export forecast CSV</button></div>${table(['Metric',...r.years.map(y=>y.year+'E')],[['revenue','Revenue'],['ebit','EBIT'],['tax','Cash taxes'],['nopat','NOPAT'],['da','Add: D&A'],['capex','Less: CapEx'],['nwc','Less: ΔNWC'],['fcf','Unlevered free cash flow'],['pv','Present value of UFCF']].map(([k,l])=>[l,...r.years.map(y=>fmt(y[k]))]))}</section><div class="grid"><section class="panel"><div class="panel-head"><div><h2>Enterprise to equity</h2><p>Inspect the bridge from operating assets to shareholders</p></div></div><div class="panel-body">${[['PV of explicit cash flows',r.pvFlows],['PV of terminal value',r.pvTerminal],['Enterprise value',r.ev],['Add cash',a.cash],['Less debt',-a.debt],['Less NCI & preferred',-a.minority-a.preferred],['Add other non-operating assets',a.other],['Equity value',r.equity]].map(([l,v])=>`<div class="bridge ${l==='Equity value'?'total':''}"><span>${l}</span><span>${fmt(v)}m</span></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2>Model review</h2><p>Judgement remains part of the analysis</p></div></div><div class="panel-body"><div class="hint ${r.terminalWeight>75?'amber':''}">${fmt(r.terminalWeight)}% of enterprise value is in the terminal period. Review sustainable growth, steady-state margins and reinvestment together.</div>${r.years[4].fcf<=0?'<div class="error">Final-year cash flow is non-positive. A perpetuity based on this value is not a defensible going-concern valuation.</div>':''}<p class="subtext">Terminal UFCF = final forecast UFCF × (1 + g). This is a simplified perpetuity, without a separate terminal ROIC schedule. No automatic lease, pension or excess-cash adjustments are made. The model does not replace a linked three-statement forecast.</p><div class="actions"><button class="primary" data-page="scenarios">Compare scenarios →</button><button data-inspect="dcf">Inspect formula</button></div></div></section></div>`:''}`;}
function waccText(){try{const r=R.wacc(wc);return `Cost of equity: ${fmt(r.ke,2)}% · Calculated WACC: ${fmt(r.value,2)}%. Weights are normalised to 100%.`;}catch(e){return esc(e.message);}}
function scenarios(){let r;try{r=R.dcf(company,a);}catch(e){return heading('SCENARIOS / MODEL COMPARISON','Test the valuation range.','Compare your saved assumptions and examine discount-rate sensitivity.')+`<div class="error">Complete a valid valuation first: ${esc(e.message)}</div><button data-page="valuation">Open valuation workbench</button>`;}return heading('SCENARIOS / MODEL COMPARISON','Test the valuation range.','Save your own cases. Compare like-for-like assumptions on the same company.')+strip()+`<section class="panel"><div class="panel-head"><div><h2>Saved model cases</h2><p>Cases persist in downloaded project files. Refreshing this page resets unsaved work.</p></div><span class="tag">${cases.length} / 6 CASES</span></div><div class="panel-body"><div class="actions"><input id="case-name" placeholder="e.g. Base case" maxlength="40" aria-label="Scenario name"><button id="save-case" class="primary">Save current model</button><span class="subtext">Current value: ${money(r.price)}</span></div></div></section><div class="case-list">${cases.map((c,i)=>{let v;try{v=R.dcf(company,c.a);}catch{}return `<div class="case"><div class="eyebrow">${esc(c.name)}</div><strong>${money(v?.price)}</strong><p>${!v?'Review equity bridge in this case':v.upside==null?'Upside unavailable':fmt(v.upside)+'% vs reference'} · WACC ${fmt(c.a.wacc)}%</p><p>Year 1 growth ${fmt(c.a.years[0].growth)}% · margin ${fmt(c.a.years[0].margin)}%</p><div class="actions"><button data-load-case="${i}">Load case</button><button data-delete-case="${i}" aria-label="Delete ${esc(c.name)}">Delete</button></div></div>`;}).join('')}</div>${!cases.length?'<div class="hint">Save a base case, change assumptions in the workbench, then save a second case. No preset is presented as a prediction.</div>':''}<section class="panel" style="margin-top:24px"><div class="panel-head"><div><h2>WACC × terminal growth</h2><p>Implied value per share. The outlined cell is the current model.</p></div><span class="tag">${company.currency} / SHARE</span></div>${table(['g ↓ / WACC →',...[-1,-.5,0,.5,1].map(d=>fmt(a.wacc+d)+'%')],[-1,-.5,0,.5,1].map((g,gi)=>[fmt(a.terminalGrowth+g)+'%',...[-1,-.5,0,.5,1].map((w,wi)=>{try{return money(R.dcf(company,{...a,wacc:a.wacc+w,terminalGrowth:a.terminalGrowth+g}).price);}catch{return 'N/M';}})]),'sensitivity')}<div class="chart-foot">Invalid WACC / growth combinations are N/M. All operating assumptions remain fixed.</div></section>`;}
function render(){const x=window.scrollY;$('#main').innerHTML=({analysis,sources,valuation,scenarios})[page]();if(page==='scenarios'){$('.sensitivity')?.rows[3]?.cells[3]?.classList.add('centre');}bind();window.scrollTo(0,x);}
function inspect(key){const h=company.history.at(-1),p=company.history.at(-2);const defs={revenue:['Revenue','Reported revenue',`Latest revenue = ${fmt(h.revenue)}m.`],ebit:['Operating profit','Reported EBIT',`Latest EBIT = ${fmt(h.ebit)}m.`],ebitda:['EBITDA','EBIT + depreciation & amortisation',`${fmt(h.ebit)} + ${fmt(h.da)} = ${fmt(R.metrics(h,p).ebitda)}m. D&A must represent operating depreciation and amortisation.`],grossMargin:['Gross margin','Reported gross profit ÷ revenue',`${fmt(h.grossProfit)} ÷ ${fmt(h.revenue)}. Missing gross profit is not silently derived.`],operatingMargin:['Operating margin','EBIT ÷ revenue',`${fmt(h.ebit)} ÷ ${fmt(h.revenue)}.`],fcf:['Cash flow after CapEx','Reported operating cash flow − capital expenditure',`${fmt(h.cfo)} − ${fmt(h.capex)} = ${fmt(R.metrics(h,p).fcf)}m. This measure follows the source CFO classification and is not the DCF’s unlevered free cash flow.`],fcfConversion:['Cash conversion','(Operating cash flow − CapEx) ÷ net income',`Net income must be positive. Latest net income = ${fmt(h.netIncome)}m.`],roic:['Return on invested capital','EBIT × (1 − assumed tax) ÷ average invested capital',`Tax assumption = 25%. Invested capital = interest-bearing debt + total equity − cash. Uses current and prior available reporting balances; not adjusted for leases, goodwill or excess cash.`],leverage:['Net leverage','(Debt − cash) ÷ (EBIT + D&A)',`(${fmt(h.debt)} − ${fmt(h.cash)}) ÷ (${fmt(h.ebit)} + ${fmt(h.da)}). Requires positive EBITDA.`],dcf:['DCF value per share','[Σ UFCFₜ / (1+WACC)ᵗ + PV(TV) + cash − debt − NCI − preferred + other assets] ÷ diluted shares',`UFCF = EBIT − cash taxes + D&A − CapEx − ΔNWC. WACC ${fmt(a.wacc)}%; shares ${fmt(a.shares)}m. Tax, reinvestment and forecast assumptions are analyst-controlled.`],ev:['Enterprise value','PV(explicit UFCF) + PV(terminal value)','Enterprise value is calculated before the enterprise-to-equity bridge.'],terminal:['Terminal value','TV = UFCF₅ × (1+g) ÷ (WACC−g); PV(TV) = TV ÷ (1+WACC)⁵',`g = ${fmt(a.terminalGrowth)}%, WACC = ${fmt(a.wacc)}%. Final-year cash flow is assumed to grow indefinitely at g.`]};const d=defs[key];$('#formula-title').textContent=d[0];$('#formula-body').innerHTML=`<code>${esc(d[1])}</code><p>${esc(d[2])}</p><p>${company.sample?'Source: fictional sample statements.':'Source inputs: '+Object.entries(company.provenance).filter(([k])=>({revenue:['revenue'],ebit:['ebit'],ebitda:['ebit','da'],grossMargin:['grossProfit','revenue'],operatingMargin:['ebit','revenue'],fcf:['cfo','capex'],fcfConversion:['cfo','capex','netIncome'],leverage:['debt','cash','ebit','da'],roic:['ebit','debt','equity','cash']})[key]?.includes(k)).map(([k,v])=>esc(`${k}: ${v.method==='analyst-verified'?v.sourceNote:v.sheet+', row '+v.row+', FY'+h.year+' column '+(v.columns[h.year]??'unavailable')}; source × ${v.sign} × ${v.unit/1e6} → millions`)).join('<br>')||'Forecast values use the analyst inputs in the workbench.'}</p>`;$('#formula').showModal();}
function modify(fn,label){const focused=document.activeElement;const focusKey=focused?.dataset.global?`[data-global="${focused.dataset.global}"]`:focused?.dataset.year!==undefined?`[data-year="${focused.dataset.year}"][data-assumption="${focused.dataset.assumption}"]`:null;let before;try{before=R.dcf(company,a).price;}catch{}fn();let after;try{after=R.dcf(company,a).price;}catch{}lastChange=before!=null&&after!=null?{before,after,label}:null;render();if(focusKey)$(focusKey)?.focus();}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));document.querySelectorAll('[data-metric]').forEach(b=>b.onclick=()=>{metric=b.dataset.metric;render();});document.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>inspect(b.dataset.inspect));
 $('#choose-file')?.addEventListener('click',()=>$('#file').click());$('#sample-import')?.addEventListener('click',()=>prepareSample());$('#cancel-import')?.addEventListener('click',()=>{pending=null;render();});
 const drop=$('#drop');if(drop){drop.ondragover=e=>{e.preventDefault();drop.classList.add('over');};drop.ondragleave=()=>drop.classList.remove('over');drop.ondrop=e=>{e.preventDefault();readFile(e.dataTransfer.files[0]);};}
 if(pending){
 $('#da-override-enabled').onchange=e=>{pending.daOverride.enabled=e.target.checked;pending.daOverride.confirmed=false;pending.confirm=false;render();};
 document.querySelectorAll('[data-da-year]').forEach(el=>el.oninput=()=>{pending.daOverride.values[el.dataset.daYear]=el.value;pending.daOverride.confirmed=false;pending.confirm=false;$('#da-verified').checked=false;$('#confirm-mapping').checked=false;});
 if($('#da-source-note'))$('#da-source-note').oninput=e=>{pending.daOverride.sourceNote=e.target.value;pending.daOverride.confirmed=false;pending.confirm=false;$('#da-verified').checked=false;$('#confirm-mapping').checked=false;};
 if($('#da-verified'))$('#da-verified').onchange=e=>{pending.daOverride.confirmed=e.target.checked;pending.confirm=false;$('#confirm-mapping').checked=false;};
 document.querySelectorAll('[data-map]').forEach(el=>el.onchange=()=>{pending.mapping[el.dataset.map]=el.value;pending.confirm=false;if(['revenue','da'].includes(el.dataset.map))render();else $('#confirm-mapping').checked=false;});document.querySelectorAll('[data-unit]').forEach(el=>el.onchange=()=>{pending.units[el.dataset.unit]=+el.value;pending.confirm=false;$('#confirm-mapping').checked=false;});document.querySelectorAll('[data-sign]').forEach(el=>el.onchange=()=>{pending.reverse[el.dataset.sign]=el.checked;pending.confirm=false;$('#confirm-mapping').checked=false;});$('#company-name').oninput=e=>pending.name=e.target.value;$('#company-ticker').oninput=e=>pending.ticker=e.target.value;$('#currency').onchange=e=>{pending.currency=e.target.value;pending.confirm=false;pending.daOverride.confirmed=false;render();};$('#confirm-mapping').onchange=e=>pending.confirm=e.target.checked;$('#apply-import').onclick=()=>{try{if(!pending.confirm)throw Error('Please confirm that you reviewed the mappings.');const c=R.build(pending.info,pending.mapping,pending);c.sample=pending.source==='Fictional sample statements';company=c;a=R.defaults(c);cases=[];pending=null;lastChange=null;go('analysis');toast('Financial data confirmed. Review available ratios and accounting checks.');}catch(e){$('#import-error').innerHTML=`<div class="error">${esc(e.message)}</div>`;}};}
 $('#confirm-bridge')?.addEventListener('change',e=>{try{a.bridgeConfirmation=e.target.checked?R.confirmBridge(a):null;lastChange=null;render();}catch(err){e.target.checked=false;toast(err.message);}});
 document.querySelectorAll('[data-global]').forEach(el=>el.onchange=()=>modify(()=>{a[el.dataset.global]=el.value===''?null:+el.value;if(R.bridgeKeys.includes(el.dataset.global))a.bridgeConfirmation=null;},el.closest('label').textContent));document.querySelectorAll('[data-year]').forEach(el=>el.onchange=()=>modify(()=>a.years[+el.dataset.year][el.dataset.assumption]=el.value===''?NaN:+el.value,el.getAttribute('aria-label')));
 $('#reset-assumptions')?.addEventListener('click',()=>{a=R.defaults(company);lastChange=null;render();});document.querySelectorAll('[data-wacc]').forEach(el=>el.onchange=()=>{wc[el.dataset.wacc]=el.value===''?NaN:+el.value;$('#wacc-result').textContent=waccText();});$('#apply-wacc')?.addEventListener('click',()=>{try{const v=R.wacc(wc).value;modify(()=>a.wacc=v,'WACC builder applied');}catch(e){toast(e.message);}});
 $('#save-case')?.addEventListener('click',()=>{const name=$('#case-name').value.trim();if(!name)return toast('Give this case a name.');if(cases.length>=6)return toast('Maximum six cases. Delete a case before adding another.');cases.push({name,a:clone(a)});render();});document.querySelectorAll('[data-load-case]').forEach(el=>el.onclick=()=>{a=clone(cases[+el.dataset.loadCase].a);lastChange=null;go('valuation');});document.querySelectorAll('[data-delete-case]').forEach(el=>el.onclick=()=>{cases.splice(+el.dataset.deleteCase,1);render();});$('#export-csv')?.addEventListener('click',()=>{const r=R.dcf(company,a),keys=['year','revenue','ebit','tax','nopat','da','capex','nwc','fcf','pv'];download('forecast.csv',[keys.join(','),...r.years.map(y=>keys.map(k=>y[k]).join(','))].join('\n'),'text/csv');});}
function prepare(sheets,source,name='Imported company',ticker='CUSTOM'){const info=R.inspect(sheets);pending={info,mapping:info.mapping,units:{},reverse:{},name,ticker,currency:'USD',source,confirm:false,daOverride:{enabled:false,values:{},sourceNote:'',confirmed:false}};go('sources');}
function prepareSample(){const rows=[['Metric',...sample.history.map(h=>h.year)],...R.fields.map(([k,l])=>[l,...sample.history.map(h=>h[k])])];prepare([{name:'Sample statements',rows}],'Fictional sample statements','Aurora Technology (sample)','AURA');}
async function readFile(file){if(!file)return;try{if(file.size>8*1024*1024)throw Error('Maximum upload size is 8 MB.');toast('Reading financial statements locally…');let sheets;if(/\.csv$/i.test(file.name))sheets=[{name:file.name,rows:FinancialImporter.parseCsv(await file.text())}];else if(/\.xlsx$/i.test(file.name))sheets=await FinancialImporter.parseXlsx(await file.arrayBuffer());else throw Error('Choose a CSV or XLSX file. PDF extraction is not supported.');prepare(sheets,file.name);toast('File read. Review the suggested mappings.');}catch(e){toast(e.message);}finally{$('#file').value='';}}
$('#file').onchange=e=>readFile(e.target.files[0]);$('#save-project').onclick=()=>download('equity-research-project.json',JSON.stringify({version:4,company,assumptions:a,cases,wacc:wc},null,2));$('#open-project').onclick=()=>$('#project-file').click();$('#project-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>8*1024*1024)throw Error('Project exceeds 8 MB.');const p=JSON.parse(await f.text());validateProject(p);company=p.company;a=p.assumptions;cases=p.cases;wc=p.wacc;pending=null;lastChange=null;go('analysis');toast('Project restored, including source mappings and saved cases.');}catch(err){toast('Cannot open project: '+err.message);}finally{e.target.value='';}};
function validateProject(p){if(p.version!==4||!p.company||!Array.isArray(p.company.history)||p.company.history.length<2||p.company.history.length>12||!['USD','GBP','EUR'].includes(p.company.currency)||typeof p.company.name!=='string'||typeof p.company.ticker!=='string'||!p.company.provenance||typeof p.company.provenance!=='object'||!Array.isArray(p.cases)||p.cases.length>6)throw Error('Unsupported or incomplete project.');let prev=0;for(const h of p.company.history){if(!Number.isInteger(h.year)||h.year<=prev||h.year<1900||h.year>2099||!(h.revenue>0))throw Error('Invalid historical periods.');prev=h.year;for(const [k] of R.fields)if(h[k]!=null&&(typeof h[k]!=='number'||!Number.isFinite(h[k])))throw Error('Invalid historical figure.');}for(const v of Object.values(p.company.provenance))if(!v||typeof v.sheet!=='string'||typeof v.label!=='string'||!v.columns||!Number.isFinite(v.unit)||![1,-1].includes(v.sign))throw Error('Invalid provenance.');const aa=p.assumptions;if(!aa||!Array.isArray(aa.years)||aa.years.length!==5)throw Error('Invalid assumptions.');for(const y of aa.years)for(const k of ['growth','margin','da','capex','nwc'])if(!Number.isFinite(y[k]))throw Error('Invalid forecast input.');for(const k of ['wacc','terminalGrowth','tax','minority','preferred','other'])if(!Number.isFinite(aa[k]))throw Error('Invalid valuation input.');for(const k of ['cash','debt','shares','marketPrice'])if(aa[k]!==null&&!Number.isFinite(aa[k]))throw Error('Invalid market input.');for(const c of p.cases){if(typeof c.name!=='string')throw Error('Invalid case name.');if(!c.a||!Array.isArray(c.a.years)||c.a.years.length!==5)throw Error('Invalid case assumptions.');for(const y of c.a.years)for(const k of ['growth','margin','da','capex','nwc'])if(!Number.isFinite(y[k]))throw Error('Invalid case forecast.');for(const k of ['wacc','terminalGrowth','tax','minority','preferred','other'])if(!Number.isFinite(c.a[k]))throw Error('Invalid case input.');for(const k of ['cash','debt','shares','marketPrice'])if(c.a[k]!=null&&!Number.isFinite(c.a[k]))throw Error('Invalid case input.');if(R.bridgeConfirmed(c.a))R.dcf(p.company,c.a);}R.wacc(p.wacc);}
$('.brand').onclick=e=>{e.preventDefault();go('analysis');};
$('.dialog-close').onclick=()=>$('#formula').close();$('#formula').onclick=e=>{if(e.target===$('#formula'))$('#formula').close();};go('analysis');
